        if(!sha.equals(AdmixtureInputs.digest(bytes)))throw new IOException("Actual decoded recipe bytes differ from their protected source hash");
        String json=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();Map<?,?> m=obj(ScviRecipeJson.parse(json));
