        Path base=source.getParent(),python=path(base,text(m,"python"));Map<?,?> l=obj(m.get("limits"));keys(l,"preset","input_bytes","decoded_bytes","workspace_bytes","retained_bytes","file_count","genes","cells","entries","sort_records","line_characters","model_bytes","wall_millis","cpu_seconds","address_space_bytes","sampled_rss_bytes","processes","threads","output_rows","output_columns");
        if(!text(l,"preset").equals("bounded-scvi-v1"))throw new IOException("Declare bounded-scvi-v1 capacities");long workspace=whole(l,"workspace_bytes",17_179_869_184L),retained=whole(l,"retained_bytes",536_870_912L);int members=integer(l,"file_count",32768);
        var matrixLimits=new ScviMatrix.Limits(whole(l,"input_bytes",4_294_967_296L),whole(l,"decoded_bytes",8_589_934_592L),workspace,retained,members,integer(l,"genes",1_000_000),integer(l,"cells",2_000_000),whole(l,"entries",100_000_000L),integer(l,"sort_records",100000),integer(l,"line_characters",1_048_576));
        var process=new ScviProcess.Limits(whole(l,"wall_millis",3600000L),whole(l,"address_space_bytes",34_359_738_368L),whole(l,"cpu_seconds",3600L),whole(l,"model_bytes",2_147_483_648L),512,workspace,members,integer(l,"processes",8),integer(l,"threads",64),whole(l,"sampled_rss_bytes",8_589_934_592L),25);
