        var kind=en(m,"kind",ScviMatrix.Kind.class);var matrix=new ScviMatrix.Request(source(base,m.get("matrix")),source(base,m.get("genes")),source(base,m.get("cells")),kind,en(m,"precision",ScviMatrix.Precision.class),en(m,"duplicates",ScviMatrix.Duplicates.class),limits);String layer=text(m,"layer");
